import boto3

class VisionClient:
    def __init__(self):
        self.rekognition_client = boto3.client('rekognition')

    def detect_labels(self, image_bytes):
        response = self.rekognition_client.detect_labels(
            Image={'Bytes': image_bytes},
            MaxLabels=10
        )
        return response

    def detect_text(self, image_bytes):
        response = self.rekognition_client.detect_text(
            Image={'Bytes': image_bytes}
        )
        return response

    def describe_image(self, image_bytes):
        response = self.rekognition_client.detect_labels(
            Image={'Bytes': image_bytes},
            MaxLabels=1
        )
        if response['Labels']:
            return response['Labels'][0]['Name']
        return 'No labels detected'

    def score_image_safety(self, image_bytes):
        response = self.rekognition_client.detect_moderation_labels(
            Image={'Bytes': image_bytes}
        )
        return response

import boto3

def score_image_safety(image_path):
    client = boto3.client('rekognition')
    with open(image_path, 'rb') as image:
        response = client.detect_moderation_labels(
            Image={'Bytes': image.read()}
        )
    return response['ModerationLabels']

import boto3

def describe_image(image_path):
    client = boto3.client('rekognition')
    with open(image_path, 'rb') as image:
        response = client.detect_labels(
            Image={'Bytes': image.read()},
            MaxLabels=10
        )
    labels = [label['Name'] for label in response['Labels']]
    return ' '.join(labels)
